{
  "early_commentary": {
    "label": "劉孝標注",
    "notes": [
      {
        "ref": "L01",
        "text": "(少清明曉悟/王隱晉書曰戎)"
      },
      {
        "ref": "L02",
        "text": "(巳見/裴頠)"
      },
      {
        "ref": "L03",
        "text": "(文王文王辟以爲掾不聞爲吏部郎/按諸書皆云鍾會薦裴楷王戎於晉)"
      }
    ]
  },
  "frozen_questions": [
    {
      "gap": "缺少關於「阿戎」與「王安豐」是指同一人（王戎）的信息，否則會誤解為鍾會評價了兩個不同的人。",
      "question_id": "Q1",
      "story_span": "鍾士季目王安豐阿戎了了解人意"
    }
  ],
  "later_commentary": {
    "label": "余嘉錫箋疏",
    "notes": [
      {
        "layer": "jianshu_note",
        "ref": "J01",
        "source_labels": [
          "太平御覽",
          "晉書"
        ],
        "speaker": "余嘉錫",
        "text": "〔一〕 嘉錫案：吏部郎以下當別為一條。吏部郎以下出王隱晉書，見御覽四百四十五。"
      },
      {
        "layer": "jianshu_note",
        "ref": "J02",
        "source_labels": [
          "太平御覽",
          "晉書"
        ],
        "speaker": "余嘉錫",
        "text": "〔二〕 程炎震云：「文選五十八褚淵碑注引臧榮緒晉書，與世說同。今晉書楷傳則又轉據臧書。孝標此駁，蓋以楷辟掾有年，則為吏部郎時，無假鍾會再薦，非謂楷不為吏部郎也。」嘉錫案：孝標謂諸書並無此事。臧榮緒書雖有之，或因榮緒齊人，後出之書不足為據。然御覽四百四十五引王隱晉書，亦與世說同，僅少「於是用裴」四字，頗疑孝標失檢。及細考之御覽，此卷所引王書自「衛玠妻父」以下凡十條，並與今晉書一字不異。蓋其閒必有一條，本引「晉書曰」，誤作「又曰」，於是諸條並蒙上文為王隱晉書矣。證以此注，尤為明白。使其事果先見王書，孝標必不束書不觀，妄發此言也。"
      }
    ]
  },
  "primary_text": {
    "label": "世說新語正文",
    "text": "鍾士季目王安豐阿戎了了解人意\n謂裴公之談經日不竭吏部郎闕文帝問其人\n\n於鍾會會曰裴楷清通王戎簡要皆其選也於是用\n裴"
  },
  "story_id": "08-shangyu-005"
}
